source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = max((v for v in counts if v != background), key=lambda v: counts[v])
    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (background, marker)]
    # The seed is a straight, three-cell motif; its middle cell is the anchor.
    rows = {r for r, c, v in seeds}
    cols = {c for r, c, v in seeds}
    if len(rows) == 1:
        axis = 1
    elif len(cols) == 1:
        axis = 0
    else:
        raise ValueError("seed cells do not form a straight line")
    seeds.sort(key=lambda x: x[axis])
    anchor = seeds[len(seeds) // 2]
    motif = [(r-anchor[0], c-anchor[1], v) for r, c, v in seeds]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for dr, dc, color in motif:
                    rr, cc = r+dr, c+dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
    return out
'''
